/* ============================================================
   十二时辰·丑·梦   丑时 01:00–03:00 ｜ 低语
   author: if love
   物件：凌晨两点摊在枕边的梦话漫画本
   风格：Y2K 网点漫画 · 蓝紫（角色/聊天区）+ 粉紫（你/顶栏/抽屉/弹窗）
   ============================================================ */
@import url('https://fonts.googleapis.com/css2?family=ZCOOL+QingKe+HuangYou&family=Noto+Serif+SC:wght@400;600&family=Space+Mono&display=swap');

:root {
  /* —— 可调变量 —— */
  --dream-bg-blur: 10px;          /* 背景模糊：0px 关闭 */
  --dream-bg-tint: rgba(14, 10, 44, .45);  /* 背景上压的夜色 */
  --dream-sticker: 1;             /* 贴纸显示：1 开 / 0 关 */

  /* —— 颜色 —— */
  --ink: #0b0820;
  --v-main: #5b45f0;   --v-mid: #1f1858;   --v-dot: #6f5cf5;
  --v-panel: rgba(30, 22, 92, .88);
  --v-lilac: #b8a2ff;  --v-paper: #ece6ff; --v-ink: #2a1d86;
  --v-text: #e4deff;   --v-sub: #bdb0ff;
  --p-main: #ff8fd0;   --p-ink: #4a0f3a;   --p-soft: #ffb3df;
  --p-panel: rgba(56, 24, 96, .94); --p-field: #0b0820; --p-line: #4a2468;
  --p-text: #f1e6ff;   --p-dim: #b58bd0;

  /* —— 字体三层 —— */
  --f-deco: 'ZCOOL QingKe HuangYou', 'Noto Sans SC', sans-serif;
  --f-body: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', serif;
  --f-label: 'Space Mono', ui-monospace, monospace;

  /* —— 素材 —— */
  --img-col-back: url(data:image/webp;base64,);
  --img-col-front: url(data:image/webp;base64,);
  --img-moon-v: url(data:image/webp;base64,);
  --img-roll-v: url(data:image/webp;base64,);
  --img-dash-v: url(data:image/webp;base64,);
  --img-spark-v: url(data:image/webp;base64,);
  --img-ht-v: url(data:image/webp;base64,);
  --img-star-p: url(data:image/webp;base64,);
  --img-peek-p: url(data:image/webp;base64,);
  --img-hang-p: url(data:image/webp;base64,);
  --img-dash-p: url(data:image/webp;base64,);
  --img-lie-p: url(data:image/webp;base64,);
  --ico-spark: url(data:image/webp;base64,);
  --ico-fish: url(data:image/webp;base64,);
  --ico-planet: url(data:image/webp;base64,);
  --ico-burst: url(data:image/webp;base64,);
  --ico-heart: url(data:image/webp;base64,);
  --ico-moon: url(data:image/webp;base64,);
  --ico-moonbun: url(data:image/webp;base64,);
  --ico-angel: url(data:image/webp;base64,);
  --ico-lie: url(data:image/webp;base64,);
  --svg-ears-p: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 62 46%22%3E%3Cg transform=%22translate(3 3) rotate(-12 15 22)%22%3E%3Cellipse cx=%2215%22 cy=%2222%22 rx=%2210%22 ry=%2220%22 fill=%22%23ffe3f3%22 stroke=%22%230b0820%22 stroke-width=%223.5%22/%3E%3Cellipse cx=%2215%22 cy=%2224%22 rx=%224.5%22 ry=%2213%22 fill=%22%23ff8fd0%22/%3E%3C/g%3E%3Cg transform=%22translate(29 1) rotate(10 15 22)%22%3E%3Cellipse cx=%2215%22 cy=%2222%22 rx=%2210%22 ry=%2220%22 fill=%22%23ffe3f3%22 stroke=%22%230b0820%22 stroke-width=%223.5%22/%3E%3Cellipse cx=%2215%22 cy=%2224%22 rx=%224.5%22 ry=%2213%22 fill=%22%23ff8fd0%22/%3E%3C/g%3E%3C/svg%3E");
  --svg-ears-v: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 62 46%22%3E%3Cg transform=%22translate(3 3) rotate(-12 15 22)%22%3E%3Cellipse cx=%2215%22 cy=%2222%22 rx=%2210%22 ry=%2220%22 fill=%22%23ece6ff%22 stroke=%22%230b0820%22 stroke-width=%223.5%22/%3E%3Cellipse cx=%2215%22 cy=%2224%22 rx=%224.5%22 ry=%2213%22 fill=%22%23b8a2ff%22/%3E%3C/g%3E%3Cg transform=%22translate(29 1) rotate(10 15 22)%22%3E%3Cellipse cx=%2215%22 cy=%2222%22 rx=%2210%22 ry=%2220%22 fill=%22%23ece6ff%22 stroke=%22%230b0820%22 stroke-width=%223.5%22/%3E%3Cellipse cx=%2215%22 cy=%2224%22 rx=%224.5%22 ry=%2213%22 fill=%22%23b8a2ff%22/%3E%3C/g%3E%3C/svg%3E");
  --svg-angel: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 104 102%22%3E%3Cg transform=%22translate(36 50) scale(-1 1) rotate(-10)%22%3E%3Cpath d=%22M40 16 Q26 0 4 4 Q14 8 6 12 Q18 14 8 19 Q22 22 14 27 Q30 28 40 16Z%22 fill=%22%23fff3fa%22 stroke=%22%230b0820%22 stroke-width=%222.5%22 stroke-linejoin=%22round%22/%3E%3C/g%3E%3Cg transform=%22translate(68 50) rotate(-10)%22%3E%3Cpath d=%22M40 16 Q26 0 4 4 Q14 8 6 12 Q18 14 8 19 Q22 22 14 27 Q30 28 40 16Z%22 fill=%22%23fff3fa%22 stroke=%22%230b0820%22 stroke-width=%222.5%22 stroke-linejoin=%22round%22/%3E%3C/g%3E%3Cg transform=%22translate(34 14) scale(.62) rotate(-14 15 22)%22%3E%3Cellipse cx=%2215%22 cy=%2222%22 rx=%2210%22 ry=%2220%22 fill=%22%23ffe3f3%22 stroke=%22%230b0820%22 stroke-width=%223.5%22/%3E%3Cellipse cx=%2215%22 cy=%2224%22 rx=%224.5%22 ry=%2213%22 fill=%22%23ff8fd0%22/%3E%3C/g%3E%3Cg transform=%22translate(52 14) scale(.62) rotate(14 15 22)%22%3E%3Cellipse cx=%2215%22 cy=%2222%22 rx=%2210%22 ry=%2220%22 fill=%22%23ffe3f3%22 stroke=%22%230b0820%22 stroke-width=%223.5%22/%3E%3Cellipse cx=%2215%22 cy=%2224%22 rx=%224.5%22 ry=%2213%22 fill=%22%23ff8fd0%22/%3E%3C/g%3E%3Cellipse cx=%2252%22 cy=%228%22 rx=%2217%22 ry=%225%22 fill=%22none%22 stroke=%22%23ff8fd0%22 stroke-width=%223%22/%3E%3C/svg%3E");
  --svg-quill: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Cpath d=%22M4 20 Q10 18 20 4 Q21 3 19 4 Q8 10 6 17 Z%22 fill=%22%23fff3fa%22 stroke=%22%230b0820%22 stroke-width=%221.5%22/%3E%3Cpath d=%22M6 17 L3 22%22 stroke=%22%23fff3fa%22 stroke-width=%221.6%22 stroke-linecap=%22round%22/%3E%3Cellipse cx=%2218%22 cy=%225%22 rx=%223.2%22 ry=%221.1%22 fill=%22none%22 stroke=%22%23ff8fd0%22 stroke-width=%221.3%22/%3E%3C/svg%3E");
  --svg-quill-v: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Cpath d=%22M4 20 Q10 18 20 4 Q21 3 19 4 Q8 10 6 17 Z%22 fill=%22%23fff3fa%22 stroke=%22%230b0820%22 stroke-width=%221.5%22/%3E%3Cpath d=%22M6 17 L3 22%22 stroke=%22%23fff3fa%22 stroke-width=%221.6%22 stroke-linecap=%22round%22/%3E%3Cellipse cx=%2218%22 cy=%225%22 rx=%223.2%22 ry=%221.1%22 fill=%22none%22 stroke=%22%23b8a2ff%22 stroke-width=%221.3%22/%3E%3C/svg%3E");
  --svg-star: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 20 20%22%3E%3Cpath d=%22M10 0 Q11 9 20 10 Q11 11 10 20 Q9 11 0 10 Q9 9 10 0Z%22 fill=%22%23fff%22/%3E%3C/svg%3E");
  --dots-v: radial-gradient(circle, var(--v-dot) 1.3px, transparent 1.5px) 0 0 / 6px 6px;
  --dots-p: radial-gradient(circle, var(--p-main) 1.3px, transparent 1.5px) 0 0 / 6px 6px;
  --dots-l: radial-gradient(circle, #a594ff 1.4px, transparent 1.6px) 0 0 / 6px 6px;
  --dots-off: radial-gradient(circle, #5a2f7a 1px, transparent 1.2px) 0 0 / 5px 5px;
}

/* ========== 全局 ========== */
body { font-family: var(--f-body); }
* { scrollbar-width: none; }
*::-webkit-scrollbar { display: none; width: 0; height: 0; }

#bg1, #bg_custom {
  filter: blur(var(--dream-bg-blur)) saturate(1.25);
  transform: scale(1.06);
}
#bg1::after, #bg_custom::after {
  content: ""; position: absolute; inset: 0; background: var(--dream-bg-tint);
}

/* ========== 顶栏 ========== */
#top-bar {
  background: rgba(10, 7, 30, .85);
  border-bottom: 2px solid #5a2a6e;
  box-shadow: none;
}
#top-settings-holder .drawer-toggle { position: relative; }
#top-settings-holder .drawer-icon {
  width: 30px; height: 30px;
  background: var(--ico-spark) center / contain no-repeat;
  color: transparent; font-size: 0;
  opacity: 1; filter: none;
  transition: transform .2s;
}
#top-settings-holder .drawer-icon::before { content: ""; }
#top-settings-holder .drawer-icon.closedIcon { opacity: 1; }
#top-settings-holder #leftNavDrawerIcon { background-image: var(--ico-spark); }
#top-settings-holder #API-status-top { background-image: var(--ico-fish); }
#top-settings-holder #advanced-formatting-button .drawer-icon { background-image: var(--ico-moon); }
#top-settings-holder #WIDrawerIcon { background-image: var(--ico-planet); }
#top-settings-holder #user-settings-button .drawer-icon { background-image: var(--ico-burst); }
#top-settings-holder #backgrounds-button .drawer-icon { background-image: var(--ico-lie); }
#top-settings-holder #extensions-settings-button .drawer-icon { background-image: var(--ico-heart); }
#top-settings-holder #persona-management-button .drawer-icon { background-image: var(--ico-angel); }
#top-settings-holder #rightNavDrawerIcon { background-image: var(--ico-moonbun); }
#top-settings-holder .drawer-icon.openIcon {
  transform: scale(1.18) rotate(-6deg);
}
#top-settings-holder .drawer-toggle:has(.openIcon)::after {
  content: ""; position: absolute; left: 50%; top: 2px;
  width: 22px; height: 7px; margin-left: -11px;
  border: 2.5px solid var(--p-main); border-radius: 50%;
  pointer-events: none;
}
#top-settings-holder .drawer-toggle:has(.openIcon)::before {
  content: ""; position: absolute; left: 50%; top: 50%;
  width: 40px; height: 40px; margin: -20px 0 0 -20px; border-radius: 50%;
  background: radial-gradient(circle, rgba(255,143,208,.55) 1.3px, transparent 1.6px) 0 0 / 5px 5px;
  -webkit-mask-image: radial-gradient(circle, #000 45%, transparent 72%);
  mask-image: radial-gradient(circle, #000 45%, transparent 72%);
  pointer-events: none;
}

/* ========== 抽屉面板（粉紫） ========== */
.drawer-content, #left-nav-panel, #right-nav-panel, #floatingPrompt, #cfgConfig {
  background:
    var(--svg-ears-p) top 0 center / 52px 34px no-repeat,
    linear-gradient(rgba(56,24,96,0) 0, var(--p-panel) 64px) 0 0 / 100% 100% no-repeat,
    var(--dots-p),
    var(--p-panel);
  background-attachment: local, scroll, scroll, scroll;
  border: 4px solid var(--ink);
  border-radius: 4px;
  box-shadow: 6px 6px 0 rgba(11,8,32,.8);
  color: var(--p-text);
  padding-top: 38px;
}
.drawer-content h3, .drawer-content h4, #left-nav-panel h3, #right-nav-panel h3,
.drawer-content .standoutHeader {
  font-family: var(--f-deco); font-weight: 400; color: #fff; letter-spacing: .06em;
}
.drawer-content small, .drawer-content .text_muted, .drawer-content .notes-link {
  font-family: var(--f-body); color: var(--p-soft);
}

#top-settings-holder .drawer-content { padding-top: 42px; }

/* 扩展抽屉 · inline-drawer（选择器和酒馆原样一致，才能盖掉它的渐变圆角条） */
.inline-drawer-toggle.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background-image: none;
  background-color: rgba(14, 8, 34, .6);
  border: 2px solid var(--ink); border-radius: 4px;
  box-shadow: 3px 3px 0 rgba(11, 8, 32, .8);
  padding: 7px 10px; margin: 4px 0 8px;
  color: var(--p-text);
}
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
.standoutHeader.inline-drawer-header:hover {
  filter: none;
  background-image: radial-gradient(circle, rgba(255,143,208,.35) 1.1px, transparent 1.3px);
  background-size: 6px 6px;
}
.inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up),
#extensions_settings .inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up),
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up),
.standoutHeader.inline-drawer-header:has(.inline-drawer-icon.up) {
  background-image: none; background-color: var(--p-main); color: var(--p-ink);
}
.inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up) * { color: var(--p-ink); }
.standoutHeader ~ .inline-drawer-content {
  border: 0; border-radius: 4px; background-color: rgba(11, 8, 32, .55);
}
.inline-drawer-header b, .inline-drawer-header strong {
  font-family: var(--f-body); font-weight: 600;
}
.inline-drawer-icon { color: var(--p-main); opacity: 1; }
.inline-drawer-icon::before { content: "▾"; font-family: var(--f-label); font-weight: 400; }
.inline-drawer-icon.up::before { content: "▴"; }
.inline-drawer-content {
  background: rgba(11, 8, 32, .55); border-radius: 4px; padding: 8px;
}

/* ========== 按钮 ========== */
.menu_button, .popup-button-ok, .popup-button-cancel, .popup-button-custom,
.mes_edit_buttons .menu_button {
  background: #f3e8ff; color: #3a1660;
  border: 3px solid var(--ink); border-radius: 0;
  box-shadow: 3px 3px 0 var(--ink);
  filter: none; opacity: 1;
  transition: transform .1s, box-shadow .1s;
}
/* 只给纯文字按钮换字体；带图标的按钮保留 FontAwesome，否则会变成方块 */
.menu_button:not(.fa-solid):not(.fa-regular):not(.fa-brands),
.popup-button-ok:not(.fa-solid), .popup-button-cancel:not(.fa-solid) {
  font-family: var(--f-deco); font-weight: 400; letter-spacing: .04em;
}
.menu_button:hover, .popup-button-ok:hover, .popup-button-cancel:hover {
  background: #ffe3f3; transform: translate(-1px, -1px); box-shadow: 4px 4px 0 var(--ink);
}
.menu_button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
.menu_button.active, .menu_button.toggleEnabled, .menu_button.popup-button-ok, .menu_button.popup-button-ok:hover {
  background: var(--p-main); color: var(--p-ink);
}
.menu_button.redWarningBG, .menu_button.caution { background: #ffb3df; color: var(--p-ink); }

/* ========== 输入框 / 选择 ========== */
.text_pole, select, textarea:not(#send_textarea), input[type="text"], input[type="number"], input[type="search"] {
  background-color: var(--p-field);
  border: 2px solid var(--p-line); border-radius: 4px;
  color: var(--p-text);
  font-family: var(--f-body);
}
.text_pole:focus, select:focus, textarea:focus, input:focus {
  border-color: var(--p-main); outline: none; box-shadow: 3px 3px 0 var(--p-main);
}
/* ST 对占位符颜色用了 !important，这里同样需要 */
.text_pole::placeholder, textarea::placeholder, input::placeholder { color: var(--p-dim) !important; opacity: 1; font-family: var(--f-body); }

/* 主题占位符（原句隐藏，用 SVG 文字替换） */
#send_textarea::placeholder, #character_search_bar::placeholder, #persona_search_bar::placeholder,
#world_info_search::placeholder, #bg-filter::placeholder, #persona_description::placeholder,
#completion_prompt_manager_popup_entry_form_prompt::placeholder,
#completion_prompt_manager_popup_entry_form_name::placeholder,
#description_textarea::placeholder, #firstmessage_textarea::placeholder,
#character_name_pole::placeholder, .world_entry textarea[name="content"]::placeholder,
.world_entry textarea[name="comment"]::placeholder { color: transparent !important; }
