#character_search_bar:placeholder-shown { background: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22143%22 height=%2222%22 viewBox=%220 0 143 22%22%3E%3Ctext x=%220%22 y=%2216%22 font-size=%2214%22 fill=%22%23b58bd0%22 font-family=%22Noto Serif SC,Source Han Serif SC,Songti SC,serif%22%3E%E5%9C%A8%E5%93%AA%E4%B8%80%E6%A0%BC%E6%A2%A6%E9%87%8C%E6%89%BE%E4%BA%BA%EF%BC%9F%3C/text%3E%3C/svg%3E") 10px 50% / auto 20px no-repeat var(--p-field); }
