#world_info_search:placeholder-shown { background: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22158%22 height=%2222%22 viewBox=%220 0 158 22%22%3E%3Ctext x=%220%22 y=%2216%22 font-size=%2214%22 fill=%22%23b58bd0%22 font-family=%22Noto Serif SC,Source Han Serif SC,Songti SC,serif%22%3E%E7%BF%BB%E6%89%BE%E5%93%AA%E4%B8%80%E6%AE%B5%E6%A2%A6%E7%9A%84%E5%9C%B0%E6%A0%87%E2%80%A6%3C/text%3E%3C/svg%3E") 10px 50% / auto 20px no-repeat var(--p-field); }
#bg-filter:placeholder-shown { background: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22113%22 height=%2222%22 viewBox=%220 0 113 22%22%3E%3Ctext x=%220%22 y=%2216%22 font-size=%2214%22 fill=%22%23b58bd0%22 font-family=%22Noto Serif SC,Source Han Serif SC,Songti SC,serif%22%3E%E6%8C%91%E4%B8%80%E9%9D%A2%E6%A2%A6%E7%9A%84%E5%A2%99%E2%80%A6%3C/text%3E%3C/svg%3E") 10px 50% / auto 20px no-repeat var(--p-field); }
