/* 滑块：冲刺兔子 */
input[type="range"] {
  -webkit-appearance: none; appearance: none;
  height: 8px; border-radius: 4px;
  background: var(--dots-off), var(--ink);
  border: 0;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 34px; height: 30px; border: 0; border-radius: 0;
  background: var(--img-dash-p) center / contain no-repeat transparent;
  box-shadow: none; cursor: grab;
}
input[type="range"]::-moz-range-thumb {
  width: 34px; height: 30px; border: 0; border-radius: 0;
  background: var(--img-dash-p) center / contain no-repeat transparent;
}
input[type="range"]::-moz-range-progress { background: var(--p-main); height: 8px; border-radius: 4px; }

/* 勾选：星星 */
input[type="checkbox"] {
  -webkit-appearance: none; appearance: none;
  width: 18px; height: 18px; flex: none;
  background: var(--ink); border: 2px solid #5a2f7a; border-radius: 0;
  cursor: pointer; position: relative; margin: 0 6px 0 0;
  outline: none; box-shadow: none; filter: none; transform: none; display: inline-grid;
}
input[type="checkbox"]:checked {
  background: var(--svg-star) center / 12px 12px no-repeat, var(--p-main);
  border-color: var(--ink);
}
input[type="checkbox"]::before, input[type="checkbox"]::after { display: none; }

/* ========== 聊天区 ========== */
/* 酒馆给消息加了 content-visibility:auto，会把伸出格子的拼贴和贴纸裁掉，这里改回可见 */
#chat .mes, #chat .mes.auto_hide, #chat > .mes, #chat > .mes:not(.last_mes) {
  content-visibility: visible; contain: none; contain-intrinsic-block-size: none;
}
#chat { padding-top: 18px; }
.mes {
  position: relative;
  width: auto; align-self: stretch; max-width: 100%; min-width: 0;
  border: 4px solid var(--ink); border-radius: 4px;
  margin: 14px 4px 40px;
  overflow: visible;
}
.mes_block, .mes_text { min-width: 0; max-width: 100%; }
.mes_text {
  font-family: var(--f-body); line-height: 1.85;
  overflow-wrap: anywhere; word-break: break-word;
}
.mes_text * { max-width: 100%; }
.mes_text pre, .mes_text code { white-space: pre-wrap; overflow-wrap: anywhere; }
.mes_text details, .mes_text summary, .mes_text table {
  max-width: 100%; white-space: normal; overflow-wrap: anywhere; box-sizing: border-box;
}
.mes_text img { height: auto; }
.mes_text q {
  background: var(--v-lilac); color: #24145e;
  padding: 1px 6px; border-radius: 10px 10px 10px 2px;
  -webkit-box-decoration-break: clone; box-decoration-break: clone;
}
.mes_text q::before, .mes_text q::after { color: #24145e; }
.mes_text em, .mes_text i { color: var(--v-sub); font-style: normal; font-size: .9em; }
/* 引用块：不要单侧色条，改成网点底的小格子 */
.mes_text blockquote, .mes_reasoning blockquote {
  border: 0; border-radius: 4px; margin: 6px 0; padding: 8px 12px;
  background: radial-gradient(circle, rgba(111,92,245,.45) 1.1px, transparent 1.3px) 0 0 / 6px 6px, rgba(11, 8, 32, .45);
}
.mes[is_user="true"] .mes_text blockquote {
  background: radial-gradient(circle, rgba(165,148,255,.6) 1.1px, transparent 1.3px) 0 0 / 6px 6px, rgba(255, 255, 255, .5);
}

/* —— 角色消息：拼贴格头 —— */
.mes[is_user="false"] {
  display: flex; flex-direction: column; align-items: stretch;
  background:
    linear-gradient(rgba(30,22,92,0) 40px, var(--v-panel) 230px) 0 0 / 100% 100% no-repeat,
    var(--dots-v),
    var(--v-panel);
  color: var(--v-text);
  padding: 0 0 14px;
  margin-top: 62px;
}
.mes[is_user="false"] { --s: 1; }
.mes[is_user="false"] .mesAvatarWrapper {
  position: relative; align-self: center; order: 0;
  width: 362px; max-width: none; height: 262px; flex: none;
  margin: -50px 0 calc(262px * (var(--s) - 1)); padding: 0;
  transform: scale(var(--s)); transform-origin: top center;
}
.mes[is_user="false"] .mesAvatarWrapper::before,
.mes[is_user="false"] .mesAvatarWrapper::after {
  content: ""; position: absolute; left: -20px; top: -20px;
  width: 402px; height: 302px; pointer-events: none;
  background: var(--img-col-back) 0 0 / 100% 100% no-repeat;
}
.mes[is_user="false"] .mesAvatarWrapper::before { z-index: 0; }
.mes[is_user="false"] .mesAvatarWrapper::after { z-index: 2; background-image: var(--img-col-front); }
.mes[is_user="false"] .avatar {
  position: absolute; z-index: 1;
  left: 113px; top: 28px; width: 136px; height: 164px;
  transform: rotate(-3deg);
  background: #f3eeff; border: 4px solid var(--ink); border-radius: 0;
  box-shadow: none; overflow: hidden;
}
.mes[is_user="false"] .avatar img {
  width: 100%; height: 100%; object-fit: cover; border-radius: 0; border: 0; box-shadow: none;
}
.mes[is_user="false"] .mesIDDisplay {
  position: absolute; z-index: 3; left: 170px; top: 236px;
  background: var(--v-paper); color: var(--v-ink);
  font-family: var(--f-label); font-size: 11px; letter-spacing: .2em;
  padding: 1px 8px; opacity: 1;
}
.mes[is_user="false"] .mesIDDisplay::before { content: "PANEL "; }
.mes[is_user="false"] .mes_timer, .mes[is_user="false"] .tokenCounterDisplay {
  position: absolute; z-index: 3; left: 18px; top: 246px;
  font-family: var(--f-label); font-size: 10px; color: var(--v-sub);
}
.mes[is_user="false"] .tokenCounterDisplay { left: auto; right: 18px; }
/* 名字压在头像下沿 */
.mes[is_user="false"] .mes_block,
.mes[is_user="false"] .ch_name,
.mes[is_user="false"] .ch_name > .flex-container,
.mes[is_user="false"] .ch_name .flex-container.flex1 { position: static; }
.mes[is_user="false"] .name_text {
  position: absolute; z-index: 3; left: 50%; top: calc(-50px + 184px * var(--s));
  transform: translateX(-50%) scale(var(--s)); transform-origin: top center;
  background: var(--ink); color: #fff;
  border: 2px solid var(--v-main);
  font-family: var(--f-deco); font-size: 22px; font-weight: 400;
  padding: 2px 16px; white-space: nowrap;
  max-width: 70%; overflow: hidden; text-overflow: ellipsis;
}
.mes[is_user="false"] .mes_block { padding: 0 16px; }
.mes[is_user="false"] .ch_name { min-height: 26px; margin-top: 4px; }
.mes[is_user="false"] .timestamp { font-family: var(--f-label); font-size: 10px; color: var(--v-sub); }
.mes[is_user="false"] .mes_text { color: var(--v-text); font-size: calc(var(--mainFontSize, 15px) * 1); }
/* 角落：抱月亮的兔子 */
.mes[is_user="false"]::after {
  content: ""; position: absolute; left: -18px; bottom: -28px;
  width: 60px; height: 60px; pointer-events: none;
  background: var(--img-moon-v) center / contain no-repeat;
  opacity: var(--dream-sticker);
}

/* —— 你的消息：雾白纸格 + 兔耳 + 天使兔子头像 —— */
.mes[is_user="true"] {
  flex-direction: row-reverse;
  margin-left: 30px; margin-right: 18px; margin-top: 46px;
  background:
    url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22160%22 height=%2290%22%3E%3Cdefs%3E%3Cpattern id=%22p%22 width=%226%22 height=%226%22 patternUnits=%22userSpaceOnUse%22%3E%3Ccircle cx=%223%22 cy=%223%22 r=%221.4%22 fill=%22%23a594ff%22/%3E%3C/pattern%3E%3ClinearGradient id=%22g%22 x1=%221%22 y1=%220%22 x2=%220.3%22 y2=%220.9%22%3E%3Cstop offset=%220%22 stop-color=%22%23fff%22/%3E%3Cstop offset=%221%22 stop-color=%22%23fff%22 stop-opacity=%220%22/%3E%3C/linearGradient%3E%3Cmask id=%22m%22%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22url(%23g)%22/%3E%3C/mask%3E%3C/defs%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22url(%23p)%22 mask=%22url(%23m)%22/%3E%3C/svg%3E") right top / 160px 90px no-repeat,
    url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22130%22 height=%2260%22%3E%3Cdefs%3E%3Cpattern id=%22p%22 width=%226%22 height=%226%22 patternUnits=%22userSpaceOnUse%22%3E%3Ccircle cx=%223%22 cy=%223%22 r=%221.4%22 fill=%22%23a594ff%22/%3E%3C/pattern%3E%3ClinearGradient id=%22g%22 x1=%220%22 y1=%221%22 x2=%220.7%22 y2=%220.1%22%3E%3Cstop offset=%220%22 stop-color=%22%23fff%22/%3E%3Cstop offset=%221%22 stop-color=%22%23fff%22 stop-opacity=%220%22/%3E%3C/linearGradient%3E%3Cmask id=%22m%22%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22url(%23g)%22/%3E%3C/mask%3E%3C/defs%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22url(%23p)%22 mask=%22url(%23m)%22/%3E%3C/svg%3E") left bottom / 130px 60px no-repeat,
    rgba(236, 230, 255, .96);
  background-clip: padding-box;
  color: var(--v-ink);
  padding: 12px 70px 14px 16px;
}
.mes[is_user="true"]::before {
  content: ""; position: absolute; left: 18px; top: -40px;
  width: 58px; height: 42px; pointer-events: none;
  background: var(--svg-ears-p) center / contain no-repeat;
}
.mes[is_user="true"]::after {
  content: ""; position: absolute; left: -28px; bottom: -28px;
  width: 60px; height: 60px; pointer-events: none;
  background: var(--img-star-p) center / contain no-repeat;
  opacity: var(--dream-sticker);
}
.mes[is_user="true"] .mesAvatarWrapper {
  position: absolute; right: -14px; top: -32px;
  width: 84px; height: 84px; z-index: 2;
}
.mes[is_user="true"] .mesAvatarWrapper::before {
  content: ""; position: absolute; inset: -14px -10px -4px; pointer-events: none;
  background: var(--svg-angel) center / contain no-repeat; z-index: 0;
}
.mes[is_user="true"] .avatar {
  position: absolute; left: 20px; top: 24px; z-index: 1;
  width: 44px; height: 44px; border-radius: 50%;
  border: 3px solid var(--ink); background: var(--p-main); overflow: hidden;
}
.mes[is_user="true"] .avatar img { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; border: 0; }
.mes[is_user="true"] .mesIDDisplay, .mes[is_user="true"] .mes_timer, .mes[is_user="true"] .tokenCounterDisplay {
  position: absolute; top: 76px; left: 0; width: 100%; text-align: center;
  font-family: var(--f-label); font-size: 10px; color: #6b56e8;
}
.mes[is_user="true"] .name_text {
  font-family: var(--f-label); font-size: 11px; letter-spacing: .22em; color: #6b56e8; font-weight: 400;
}
.mes[is_user="true"] .name_text::before { content: "PANEL · "; }
.mes[is_user="true"] .mes_text, .mes[is_user="true"] .mes_text p { color: var(--v-ink); }
.mes[is_user="true"] .mes_text em { color: #6b56e8; }
.mes[is_user="true"] .mes_text q { background: var(--p-main); color: var(--p-ink); }
.mes[is_user="true"] .mes_text q::before, .mes[is_user="true"] .mes_text q::after { color: var(--p-ink); }
.mes[is_user="true"] .timestamp { color: #6b56e8; font-family: var(--f-label); font-size: 10px; }
.mes[is_user="true"] .mes_buttons, .mes[is_user="true"] .mes_buttons * { color: #6b56e8; }

/* —— 消息操作：小羽毛 —— */
.mes_buttons { color: var(--v-sub); }
.mes_buttons .mes_button, .extraMesButtons > div { opacity: 1; filter: none; }
.mes_edit::before, .mes .mes_edit::before { content: ""; }
.mes_edit {
  width: 20px; height: 20px;
  background: var(--svg-quill-v) center / contain no-repeat;
}
.mes[is_user="true"] .mes_edit { background-image: var(--svg-quill); }
.extraMesButtonsHint::before { content: "⋯"; font-family: var(--f-label); }

/* 编辑中 */
.mes .edit_textarea {
  background: var(--ink); color: var(--v-text);
  border: 2px solid #3a2f8a; border-radius: 4px;
  font-family: var(--f-body); line-height: 1.8;
}
.mes[is_user="true"] .edit_textarea { color: var(--p-text); }
.mes_edit_buttons .menu_button { width: auto; padding: 2px 8px; margin: 0 3px; }
.mes_edit_buttons .mes_edit_done { background: var(--v-main); color: #fff; }

/* 翻页 */
.swipe_left, .swipe_right { color: var(--v-sub); opacity: 1; filter: none; }
.swipes-counter {
  background: var(--v-paper); color: var(--v-ink);
  border: 2px solid var(--ink); padding: 0 8px;
  font-family: var(--f-label); font-size: 12px; opacity: 1;
}

/* 正在输入：团成一团的兔子 */
.typing_indicator {
  font-family: var(--f-label); font-size: 11px; letter-spacing: .2em; color: var(--v-sub);
  display: flex; align-items: center; gap: 6px;
}
.typing_indicator::before {
  content: ""; width: 28px; height: 28px; flex: none;
  background: var(--img-roll-v) center / contain no-repeat;
  animation: dream-roll 1.2s linear infinite;
}
@keyframes dream-roll { to { transform: rotate(360deg); } }

/* 系统消息 / 旁白 */
.mes.smallSysMes, .mes[is_system="true"] {
  background: var(--dots-v), rgba(11, 8, 32, .7);
}
.mes.smallSysMes::after, .mes[is_system="true"]::after { display: none; }

/* ========== 输入区 ========== */
#send_form {
  background: rgba(10, 7, 30, .88);
  border: 2px solid var(--ink); border-radius: 18px;
  box-shadow: 4px 4px 0 rgba(11,8,32,.8);
  margin-bottom: 6px;
}
#send_textarea {
  color: var(--v-text); font-family: var(--f-body);
  background-color: transparent;
}
#send_but, #mes_continue, #mes_impersonate {
  color: transparent; font-size: 0;
}
#send_but {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--img-dash-v) center / 40px auto no-repeat, var(--v-main);
  border: 2px solid var(--ink); opacity: 1;
}
#send_but::before { content: ""; }
#mes_stop { color: var(--p-main); }
#options_button, #extensionsMenuButton, #leftSendForm > div, #rightSendForm > div:not(#send_but) {
  color: var(--v-sub); opacity: 1;
}
#options, #extensionsMenu, .list-group {
  background: var(--dots-p) top / 6px 6px, var(--p-panel);
  border: 3px solid var(--ink); border-radius: 4px;
  box-shadow: 4px 4px 0 var(--ink);
}
#options .options-content a, .list-group-item { color: var(--p-text); font-family: var(--f-body); }
#options .options-content a:hover, .list-group-item:hover { background: rgba(255,143,208,.2); }

/* ========== 预设条目（关闭不变灰） ========== */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background: rgba(14, 8, 34, .6);
  border: 0; border-radius: 4px; margin-bottom: 6px;
  color: var(--p-text);
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background: var(--dots-off), rgba(14, 8, 34, .9);
  border: 0; opacity: 1; filter: none; color: var(--p-text);
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: var(--p-text); opacity: 1; text-decoration: none;
}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name::after {
  content: " ZZZ"; font-family: var(--f-label); font-size: 11px; letter-spacing: .2em; color: var(--p-main);
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name { color: var(--p-text); }
#completion_prompt_manager_list .completion_prompt_manager_list_head {
  font-family: var(--f-label); letter-spacing: .2em; color: var(--p-soft); background: transparent;
}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
  opacity: 1; filter: none;
}
/* 开关 */
.prompt-manager-toggle-action, .world_entry .killSwitch {
  width: 36px; height: 20px; border-radius: 10px; flex: none;
  border: 2px solid var(--ink); color: transparent; font-size: 0;
  background: radial-gradient(circle at 25px 50%, #fff3fa 6px, #b04a90 7px, #b04a90 8px, transparent 8.5px), var(--p-main);
  opacity: 1; filter: none; cursor: pointer;
}
.prompt-manager-toggle-action::before, .world_entry .killSwitch::before { content: ""; }
.prompt-manager-toggle-action.fa-toggle-off, .world_entry .killSwitch.fa-toggle-off {
  border-color: #5a2f7a;
  background: radial-gradient(circle at 9px 50%, #5a2f7a 6px, transparent 6.5px), var(--ink);
}
/* 小羽毛 */
.prompt-manager-edit-action, .world_entry .fa-pencil {
  color: transparent; font-size: 0; width: 20px; height: 20px;
  background: var(--svg-quill) center / contain no-repeat;
  opacity: 1;
}
.prompt-manager-edit-action::before, .world_entry .fa-pencil::before { content: ""; }

/* 编辑弹窗：关闭的条目也清楚 */
#completion_prompt_manager_popup, #completion_prompt_manager_popup * { opacity: 1; filter: none; }
#completion_prompt_manager_popup {
  background:
    var(--img-hang-p) left 10px top 4px / 64px auto no-repeat,
    linear-gradient(rgba(56,24,96,0) 0, var(--p-panel) 60px) 0 0 / 100% 100% no-repeat,
    var(--dots-p), var(--p-panel);
  color: var(--p-text);
  border: 4px solid var(--ink); border-radius: 4px;
}
#completion_prompt_manager_popup h3, #completion_prompt_manager_popup_header {
  font-family: var(--f-deco); font-weight: 400; color: #fff; padding-left: 70px;
}
#completion_prompt_manager_popup label, #completion_prompt_manager_popup .text_muted {
  font-family: var(--f-label); font-size: 12px; letter-spacing: .12em; color: var(--p-soft);
}

/* ========== 世界书 ========== */
#WorldInfo .world_entry, .world_entry {
  background: rgba(14, 8, 34, .6); border-radius: 4px; border: 0; margin-bottom: 6px;
}
.world_entry.disabledWIEntry, .world_entry .disabledWIEntry, .world_entry.disabledWIEntry:not(input):hover, .world_entry:has(.killSwitch.fa-toggle-off) {
  opacity: 1; filter: none;
  background: var(--dots-off), rgba(14, 8, 34, .9);
}
.world_entry:has(.killSwitch.fa-toggle-off) .WIEntryTitleAndStatus::after {
  content: "ZZZ"; font-family: var(--f-label); font-size: 11px; letter-spacing: .2em; color: var(--p-main); margin-left: 6px;
}
.world_entry * { opacity: 1; }

/* ========== 角色列表 ========== */
#rm_print_characters_block .character_select, #rm_print_characters_block .group_select, .bogus_folder_select {
  position: relative;
  background: rgba(14, 8, 34, .5); border-radius: 4px; margin: 4px 0 10px;
  padding: 6px 8px 6px 6px;
}
#rm_print_characters_block .character_select .avatar, #rm_print_characters_block .group_select .avatar {
  border-radius: 0; border: 3px solid var(--ink);
  box-shadow: 5px 5px 0 0 var(--v-main);
  background: var(--img-ht-v) center / cover;
  transform: rotate(-2deg);
}
#rm_print_characters_block .avatar img { border-radius: 0; }
#rm_print_characters_block .ch_name {
  font-family: var(--f-deco); font-size: 17px; color: #fff;
  background: var(--v-main); padding: 0 8px; border: 2px solid var(--ink); display: inline-block;
}
#rm_print_characters_block .character_select.is_fav .ch_name { background: var(--p-main); color: var(--p-ink); }
#rm_print_characters_block .ch_description, #rm_print_characters_block .ch_additional_info {
  color: var(--p-dim); font-family: var(--f-body);
}
.paginationjs-pages li.active > a { background: var(--p-main); color: var(--p-ink); border: 2px solid var(--ink); }
.paginationjs-pages li > a { color: var(--p-soft); font-family: var(--f-label); }
#avatar_div_div img, #avatar_load_preview { border-radius: 0; border: 4px solid var(--ink); }

/* ========== 用户设定 ========== */
#user_avatar_block .avatar-container .avatar, #user_avatar_block .avatar-container .avatar img {
  border-radius: 50%;
}
#user_avatar_block .avatar-container .avatar { border: 3px solid var(--ink); background: var(--p-main); }
#user_avatar_block .avatar-container.selected { position: relative; }
#user_avatar_block .avatar-container.selected .avatar { box-shadow: 0 0 0 3px var(--p-main); }
#user_avatar_block .avatar-container.selected::before {
  content: ""; position: absolute; left: 50%; top: -6px; width: 30px; height: 9px; margin-left: -15px;
  border: 2.5px solid var(--p-main); border-radius: 50%; z-index: 2; pointer-events: none;
}
#user_avatar_block .avatar-container .ch_name { font-family: var(--f-deco); color: #fff; }
#persona-management-block::after {
  content: ""; position: sticky; float: right; bottom: 0; width: 64px; height: 64px;
  background: var(--img-star-p) center / contain no-repeat; opacity: var(--dream-sticker);
}

/* ========== 弹窗 ========== */
dialog.popup, .popup {
  overflow: visible;
  background:
    linear-gradient(rgba(56,24,96,0) 0, var(--p-panel) 56px) 0 0 / 100% 100% no-repeat,
    var(--dots-p), var(--p-panel);
  color: var(--p-text);
  border: 4px solid var(--ink); border-radius: 4px;
  box-shadow: 6px 6px 0 var(--ink);
  margin-top: 70px;
}
dialog.popup::before, .popup::before {
  content: ""; position: absolute; left: 50%; top: -66px; width: 80px; height: 80px; margin-left: -40px;
  background: var(--img-peek-p) center bottom / contain no-repeat; pointer-events: none;
}
.popup h3, .popup h2, .popup .popup-content h3 { font-family: var(--f-deco); font-weight: 400; color: #fff; }
.popup .popup-controls { gap: 14px; }

/* 提示条 */
#toast-container > .toast, #toast-container > div {
  background-color: var(--p-panel); background-image: none;
  border: 3px solid var(--ink); border-radius: 4px; box-shadow: 4px 4px 0 var(--ink);
  color: var(--p-text); font-family: var(--f-body); opacity: 1;
}
#toast-container > .toast-error { background-color: #5a1640; }
#toast-container > .toast-success { background-color: #2a2380; }

/* ========== 背景 / 杂项 ========== */
.bg_example { border: 3px solid var(--ink); border-radius: 0; }
.bg_example.selected, .bg_example:has(.selected) { box-shadow: 0 0 0 3px var(--p-main); }
.fa-solid, .fa-regular { opacity: 1; }
hr { border: 0; height: 6px; background: var(--dots-off); opacity: 1; }
a { color: var(--p-soft); }

/* ========== 手机 ========== */
@media (max-width: 1000px) {
  .mes { margin-left: 2px; margin-right: 2px; }
  .mes[is_user="true"] { margin-left: 26px; margin-right: 18px; }
  .drawer-content { min-width: 0; }
}
@media (max-width: 440px) { .mes[is_user="false"] { --s: .92; } }
@media (max-width: 390px) { .mes[is_user="false"] { --s: .86; } }
@media (max-width: 350px) { .mes[is_user="false"] { --s: .78; } }
